import {
  pgTable,
  uuid,
  text,
  integer,
  jsonb,
  timestamp,
  boolean,
  index,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

/**
 * Hub Price Calculator — PNG upload + Printavo push metadata.
 *
 * Each row represents a single PNG calculation screenshot generated by the Hub
 * Price Calculator. A row is created when the client requests an upload URL,
 * then mutated as the push progresses through Printavo.
 *
 * Design constraints:
 * - No foreign keys to pv_* tables (sync may delete/reinsert them).
 * - `publicToken` is a 64-char hex high-entropy token used in the public URL.
 * - `dedupeKey` enforces exactly-once reservations for identical reviewed
 *   snapshots — concurrent inserts race on the unique constraint; the loser
 *   re-reads and reuses the winner's row.
 * - `noteAttemptedAt` / `fileAttemptedAt` are set atomically before each
 *   non-idempotent Printavo call. If either timestamp is set without confirmed
 *   completion, no later request may issue that mutation again.
 * - `productionFileId` is set exactly once — never re-created on retry.
 */
export type HubCalcUploadStatus =
  | "pending"       // Upload slot reserved, PNG not yet confirmed
  | "uploaded"      // PNG verified in object storage
  | "note_ok"       // productionNote updated in Printavo
  | "file_ok"       // productionFileCreate succeeded (note + file both done)
  | "note_failed"   // productionNote write failed (confirmed error)
  | "file_failed"   // productionFileCreate threw (confirmed error before Printavo accepted)
  | "file_locked"   // productionFileCreate result ambiguous — manual verification required
  | "partial";      // Note succeeded but file failed/locked

export const hubCalcUploadsTable = pgTable(
  "hub_calc_uploads",
  {
    id: uuid("id").primaryKey().defaultRandom(),

    /** Internal Printavo invoice id (GraphQL id). */
    invoiceId: text("invoice_id").notNull(),

    /** Visible invoice number shown in Printavo UI (from local mirror at reservation). */
    visualId: integer("visual_id").notNull(),

    /** Quote number from the calculator (e.g. "1234"). Required for note identity. */
    quoteNumber: text("quote_number"),

    /**
     * Validated range key — one of the enumerated range strings:
     * "all", "12-48", "36-72", "60-96", "84-120", "108-144", "144-288".
     */
    rangeKey: text("range_key").notNull(),

    /** Full GCS object path for the uploaded PNG, e.g. "/bucket/hub-calc/uploads/<uuid>.png". */
    objectPath: text("object_path").notNull(),

    /**
     * GCS generation recorded after the staging upload is copied to a
     * server-owned finalized object. Any later generation change fails closed.
     */
    objectGeneration: text("object_generation"),

    /**
     * High-entropy 64-char hex public token for the unauthenticated serve URL.
     * Never changes after creation.
     */
    publicToken: text("public_token")
      .notNull()
      .default(
        sql`replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '')`,
      ),

    /**
     * Sanitized filename for the public URL (e.g. "hub-calc-Q1234.png").
     * Stored so the URL is stable even if quoteNumber changes.
     */
    publicFilename: text("public_filename").notNull(),

    /** Current upload/push lifecycle status. */
    status: text("status")
      .$type<HubCalcUploadStatus>()
      .notNull()
      .default("pending"),

    /**
     * Optional staff note attached at push time (display in Hub only).
     */
    note: text("note"),

    /**
     * Canonical deduplification key — SHA-256 hex of the canonical payload
     * (invoiceId + visualId + quoteNumber + rangeKey + sorted price rows).
     * Unique constraint: identical reviewed snapshots return/re-sign the
     * existing row rather than creating a duplicate.
     */
    dedupeKey: text("dedupe_key").notNull(),

    /**
     * The selected price rows as JSON snapshot (stored at reservation, validated
     * at push). Shape: Array<{ qty: number; unitPrice: number }>
     */
    priceRows: jsonb("price_rows"),

    /**
     * Optional validated line-item snapshot reviewed with this calculator push.
     * Null means the push only updates Production Notes + the PNG.
     */
    lineItemSnapshot: jsonb("line_item_snapshot"),

    /**
     * Multi-style note sections (Compare schedules or Mixed order lines) for
     * ONE Production Notes block. Null = legacy single-style priceRows block.
     */
    noteSections: jsonb("note_sections"),

    /**
     * Printavo productionFile id, set once after a successful
     * productionFileCreate and never overwritten (prevents duplicate attaches).
     */
    productionFileId: text("production_file_id"),

    /** Set once immediately before the non-idempotent lineItemGroupCreate call. */
    lineItemAttemptedAt: timestamp("line_item_attempted_at", { withTimezone: true }),

    /** Confirmed ids returned by Printavo after creating the group + line item. */
    lineItemGroupId: text("line_item_group_id"),
    lineItemId: text("line_item_id"),

    /** Ambiguous/confirmed error from line-item creation; an attempted row is never retried. */
    lineItemError: text("line_item_error"),
    lineItemErrorAt: timestamp("line_item_error_at", { withTimezone: true }),

    /**
     * Set atomically (via conditional UPDATE … WHERE note_attempted_at IS NULL)
     * immediately before calling client.mutate for invoiceUpdate. If set without
     * noteOk=true, no future request may re-issue the note mutation; a live read
     * may recover to note_ok if the exact block is already present.
     */
    noteAttemptedAt: timestamp("note_attempted_at", { withTimezone: true }),

    /** True once the note mutation returned without error. */
    noteOk: boolean("note_ok").notNull().default(false),

    /** Last Printavo note-update error message. */
    noteError: text("note_error"),

    /** ISO timestamp of the last Printavo note-update error. */
    noteErrorAt: timestamp("note_error_at", { withTimezone: true }),

    /**
     * Set atomically (via conditional UPDATE … WHERE file_attempted_at IS NULL)
     * immediately before calling client.mutate for productionFileCreate. If set
     * without productionFileId being populated, the result is ambiguous and the
     * row is permanently locked for manual verification — no retry allowed.
     */
    fileAttemptedAt: timestamp("file_attempted_at", { withTimezone: true }),

    /** Last Printavo file-attach error message. */
    fileError: text("file_error"),

    /** ISO timestamp of the last Printavo file-attach error. */
    fileErrorAt: timestamp("file_error_at", { withTimezone: true }),

    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("hub_calc_uploads_invoice_id_idx").on(t.invoiceId),
    index("hub_calc_uploads_created_at_idx").on(t.createdAt),
    uniqueIndex("hub_calc_uploads_public_token_uq").on(t.publicToken),
    uniqueIndex("hub_calc_uploads_dedupe_key_uq").on(t.dedupeKey),
  ],
);

export type HubCalcUpload = typeof hubCalcUploadsTable.$inferSelect;
export type InsertHubCalcUpload = typeof hubCalcUploadsTable.$inferInsert;
